From aa4a8b8967577a1fbc72097643cd384db6f8257a Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 22:13:10 +0100
Subject: [PATCH] applets/devicenotifier: don't offer Open in File Manager for
 blank discs

A blank CD, DVD or Blu-ray has no file system, so its Open in File Manager
button could only open the home folder. Make the default action invalid
for blank optical discs and hide the button when it isn't valid.

BUG: 469704
---
 applets/devicenotifier/actions/mountandopenaction.cpp | 6 +++++-
 applets/devicenotifier/actions/mountandopenaction.h   | 1 +
 applets/devicenotifier/actionsinfo.cpp                | 5 +++++
 applets/devicenotifier/actionsinfo.h                  | 2 ++
 applets/devicenotifier/qml/DeviceItem.qml             | 2 +-
 5 files changed, 14 insertions(+), 2 deletions(-)

diff --git a/applets/devicenotifier/actions/mountandopenaction.cpp b/applets/devicenotifier/actions/mountandopenaction.cpp
index 454bba10f8..234fedd6ac 100644
--- a/applets/devicenotifier/actions/mountandopenaction.cpp
+++ b/applets/devicenotifier/actions/mountandopenaction.cpp
@@ -22,6 +22,7 @@ MountAndOpenAction::MountAndOpenAction(const std::shared_ptr<StorageInfo> &stora

     m_hasStorageAccess = false;
     m_isOpticalDisk = false;
+    m_isBlankDisc = false;
     m_isRoot = false;

     m_hasPortableMediaPlayer = false;
@@ -40,6 +41,9 @@ MountAndOpenAction::MountAndOpenAction(const std::shared_ptr<StorageInfo> &stora
                 m_isOpticalDisk = true;
             }
         }
+    } else if (device.is<Solid::OpticalDisc>()) {
+        auto *opticaldisc = device.as<Solid::OpticalDisc>();
+        m_isBlankDisc = opticaldisc && opticaldisc->isBlank();
     }

     if (device.is<Solid::PortableMediaPlayer>()) {
@@ -106,7 +110,7 @@ QString MountAndOpenAction::predicate() const

 bool MountAndOpenAction::isValid() const
 {
-    return true;
+    return !m_isBlankDisc;
 }

 QString MountAndOpenAction::name() const
diff --git a/applets/devicenotifier/actions/mountandopenaction.h b/applets/devicenotifier/actions/mountandopenaction.h
index 39ce3816d0..b9156089af 100644
--- a/applets/devicenotifier/actions/mountandopenaction.h
+++ b/applets/devicenotifier/actions/mountandopenaction.h
@@ -38,6 +38,7 @@ private Q_SLOTS:
 private:
     bool m_hasStorageAccess;
     bool m_isOpticalDisk;
+    bool m_isBlankDisc;
     bool m_isRoot;

     bool m_hasCamera;
diff --git a/applets/devicenotifier/actionsinfo.cpp b/applets/devicenotifier/actionsinfo.cpp
index 92cf83679a..977f75f5f5 100644
--- a/applets/devicenotifier/actionsinfo.cpp
+++ b/applets/devicenotifier/actionsinfo.cpp
@@ -66,6 +66,11 @@ QString ActionsInfo::defaultActionName() const
     return m_defaultAction->name();
 }

+bool ActionsInfo::isDefaultActionValid() const
+{
+    return m_defaultAction->isValid();
+}
+
 QString ActionsInfo::defaultActionIcon() const
 {
     return m_defaultAction->icon();
diff --git a/applets/devicenotifier/actionsinfo.h b/applets/devicenotifier/actionsinfo.h
index 21b44d72d2..165a63e77e 100644
--- a/applets/devicenotifier/actionsinfo.h
+++ b/applets/devicenotifier/actionsinfo.h
@@ -24,6 +24,7 @@ class ActionsInfo : public QAbstractListModel
     QML_UNCREATABLE("Non-createable type that is associated with a specific device")

     Q_PROPERTY(QString defaultActionName READ defaultActionName CONSTANT)
+    Q_PROPERTY(bool defaultActionValid READ isDefaultActionValid CONSTANT)
     Q_PROPERTY(QString defaultActionIcon READ defaultActionIcon NOTIFY defaultActionIconChanged)
     Q_PROPERTY(QString defaultActionText READ defaultActionText NOTIFY defaultActionTextChanged)

@@ -52,6 +53,7 @@ public:

 private:
     QString defaultActionName() const;
+    bool isDefaultActionValid() const;
     QString defaultActionIcon() const;
     QString defaultActionText() const;

diff --git a/applets/devicenotifier/qml/DeviceItem.qml b/applets/devicenotifier/qml/DeviceItem.qml
index e1b0258e2e..8437a04225 100644
--- a/applets/devicenotifier/qml/DeviceItem.qml
+++ b/applets/devicenotifier/qml/DeviceItem.qml
@@ -127,7 +127,7 @@ PlasmaExtras.ExpandableListItem {
         return Kirigami.Theme.textColor;
     }

-    defaultActionButtonAction: deviceActions !== undefined && isFree ? defaultAction : null
+    defaultActionButtonAction: deviceActions !== undefined && deviceActions.defaultActionValid && isFree ? defaultAction : null

     QQC2.Action {
         id: defaultAction
-- 
2.53.0
